service.method:

DELETE 
  FROM #DB_OWNER#SGRID
 WHERE GRID_ID    = ${GRID_ID} 
   AND CODE       = ${CODE}
   AND HOUSE_CODE = '000'


SELECT COUNT(*) 
  FROM SGRID 
 WHERE GRID_ID    = ${GRID_ID} 
   AND CODE       = ${CODE}
   AND HOUSE_CODE = '000'

UPDATE #DB_OWNER#SGRID SET COL_TYPE = ${COL_TYPE}, MODULE = ${MODULE}, COL_FORMAT = ${COL_FORMAT}, COL_MAX_LEN = ${COL_MAX_LEN}, COL_ALIGN = ${COL_ALIGN}, COL_VISIBLE = ${COL_VISIBLE}, SELECTED_YN = ${SELECTED_YN}, COL_SEQ = ${COL_SEQ}, TEXT_STYLE = ${TEXT_STYLE}, COL_COLOR = ${COL_COLOR}, COL_COMBO = ${COL_COMBO}, COL_SORT = ${COL_SORT}, CHANGE_USER_ID = ${session.ID}, CHANGE_DATE = ${current.DATE}, CHANGE_TIME = ${current.TIME}, NOT_NULL = ${NOT_NULL}, TEMPLATE = ${TEMPLATE} WHERE 1=1
AND GRID_ID = ${GRID_ID}
AND CODE = ${CODE} AND HOUSE_CODE = '000'


SELECT COUNT(*) 
  FROM SLANG 
 WHERE SCREEN_ID  = ${GRID_ID} 
   AND CODE       = ${CODE}
   AND LANGUAGE   = ${LANGUAGE}
   AND HOUSE_CODE = '000'


	UPDATE #DB_OWNER#SLANG 
       SET CONTENTS    = ${CONTENTS}
		 , GRID_WIDTH  = ${COL_WIDTH}
		 , CHANGE_DATE = ${current.DATE}
		 , CHANGE_TIME = ${current.TIME}
     WHERE SCREEN_ID  = ${GRID_ID}
       AND CODE       = ${CODE}
       AND HOUSE_CODE = '000'
       AND LANGUAGE   = ${LANGUAGE}


INSERT
    INTO #DB_OWNER#SGRID_HISTORY
      (
          HISTORY_KEY
        , ACTION_MODE
        , HOUSE_CODE
        , GRID_ID
        , CODE
        , ADD_USER_ID
        , ADD_DATE
        , ADD_TIME
        , COL_TYPE
        , COL_FORMAT
        , COL_WIDTH
        , COL_MAX_LEN
        , COL_ALIGN
        , COL_VISIBLE
        , SELECTED_YN
        , COL_SEQ
        , COL_COLOR
        , COL_COMBO
        , COL_SORT
        , ACC_DATE
        , NOT_NULL
        , TEMPLATE
        , TEXT_STYLE
        , MODULE
      )
VALUES(
          ${HISTORY_KEY}
        , ${ACTION_MODE}
        , ${session.HOUSE_CODE}
        , ${GRID_ID}
        , ${CODE}
        , ${session.ID}
        , ${current.DATE}
        , ${current.TIME}
        , ${COL_TYPE}
        , ${COL_FORMAT}
        , ${COL_WIDTH}
        , ${COL_MAX_LEN}
        , ${COL_ALIGN}
        , ${COL_VISIBLE}
        , ${SELECTED_YN}
        , ${COL_SEQ}
        , ${COL_COLOR}
        , ${COL_COMBO}
        , ${COL_SORT}
        , ${ACC_DATE}
        , ${NOT_NULL}
        , ${TEMPLATE}
        , ${TEXT_STYLE}
        , ${MODULE}
      )


INSERT
    INTO #DB_OWNER#SLANG_HISTORY
      (
          HISTORY_KEY
        , ACTION_MODE
        , HOUSE_CODE
        , SCREEN_ID
        , LANGUAGE
        , CODE
        , CONTENTS
        , ADD_USER_ID
        , ADD_DATE
        , ADD_TIME
        , GRID_WIDTH
        , FORM_WIDTH
      )
VALUES(
          ${HISTORY_KEY}
        , ${ACTION_MODE}
        , ${session.HOUSE_CODE}
        , ${GRID_ID}
        , ${LANGUAGE}
        , ${CODE}
        , ${CONTENTS}
        , ${session.ID}
        , ${current.DATE}
        , ${current.TIME}
        , ${COL_WIDTH}
        , ${FORM_WIDTH}
     )
